-- 口コミの項目を足し、AIで作ったダミーの口コミを入れる（第10回MTG）
-- 001〜003 のあとに実行する。何度実行しても同じ結果になる（ダミーの口コミは入れ直す）

-- ① 細分化した星（1〜5。楽天トラベルの評価項目に合わせる）。カテゴリに合わない項目は空のまま
--    宿: すべて／レジャー: サービス・立地・設備／食事: サービス・立地・食事
alter table bts_app.posts add column if not exists rating_service int check (rating_service between 1 and 5);
alter table bts_app.posts add column if not exists rating_location int check (rating_location between 1 and 5);
alter table bts_app.posts add column if not exists rating_room int check (rating_room between 1 and 5);
alter table bts_app.posts add column if not exists rating_equipment int check (rating_equipment between 1 and 5);
alter table bts_app.posts add column if not exists rating_bath int check (rating_bath between 1 and 5);
alter table bts_app.posts add column if not exists rating_meal int check (rating_meal between 1 and 5);

-- ② お得感の満足度（1〜5）。4以上を「満足」とし、施設ごとの満足の割合をランキングの減点に使う
alter table bts_app.posts add column if not exists deal_rating int check (deal_rating between 1 and 5);

-- ③ ダミーデータの印。本番前に「delete from bts_app.posts where is_sample;」で消せる
alter table bts_app.posts add column if not exists is_sample boolean not null default false;

-- ④ ダミーの口コミを入れ直す（68件。0件・10件以上・満足度が低い施設を含む）
delete from bts_app.posts where is_sample;

